  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    gap_threshold = extra.get('gap_threshold', 0.0)\n    # objective shape: [B, N]; lower is better\n    diff = objective[:, :, None] - objective[:, None, :]\n    # winner i over loser j if objective[i] + gap_threshold < objective[j]\n    mask = diff < (-gap_threshold)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_threshold', 'gap_threshold': gap_threshold})\n"
}

